def max_product(num_str: str, N: int, K: int) -> int:
    # Convert the string to a list of digits
    digits = [int(c) for c in num_str]

    # If K is 0, return the number itself
    if K == 0:
        return int(num_str)

    # If K >= N-1, we can split into single digits
    if K >= N - 1:
        product = 1
        for d in digits:
            product *= d
        return product

    # dp[i][j] = maximum product for the first i digits with j multiplication signs
    # i ranges from 1 to N, j ranges from 0 to K
    # We use -1 to indicate impossible states
    dp = [[-1] * (K + 1) for _ in range(N + 1)]

    # Base case: no multiplication signs, the product is the number formed by first i digits
    for i in range(1, N + 1):
        dp[i][0] = int(num_str[:i])

    # Fill the dp table
    for i in range(1, N + 1):
        for j in range(1, min(i - 1, K) + 1):
            # We need to place j multiplication signs in the first i digits
            # The last multiplication sign can be placed at position k (1 <= k < i)
            # Then the last segment is from k to i-1 (0-indexed), i.e., num_str[k:i]
            # And we need j-1 multiplication signs in the first k digits
            best = -1
            for k in range(j, i):  # k is the number of digits in the left part, must be at least j (to place j-1 signs)
                if dp[k][j - 1] != -1:
                    right_part = int(num_str[k:i])
                    product = dp[k][j - 1] * right_part
                    if product > best:
                        best = product
            dp[i][j] = best

    return dp[N][K]

